package com.rafi.daybook;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import org.json.*;import java.util.Calendar;
public class ReminderReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context c,Intent i){try{JSONObject r=new JSONObject(i.getStringExtra("item"));int id=i.getIntExtra("number",1);NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("daybook","Daybook reminders",NotificationManager.IMPORTANCE_HIGH));Intent open=new Intent(c,MainActivity.class);PendingIntent tap=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)nm.notify(id,new Notification.Builder(c,"daybook").setSmallIcon(android.R.drawable.ic_menu_my_calendar).setContentTitle("Daybook").setContentText(r.getString("title")).setContentIntent(tap).setAutoCancel(true).build());if(r.has("annualMonth")){Calendar year=Calendar.getInstance(),next=Calendar.getInstance();next.clear();next.set(year.get(Calendar.YEAR)+1,r.getInt("annualMonth")-1,r.getInt("annualDay"),0,0,0);r.put("at",next.getTimeInMillis());Reminders.schedule(c,id,r);}}catch(JSONException ignored){}}
}
